var o=[{base:"mastodon_mock_token",storage:"local",suffix:"none",sensitivity:"secret",note:"Active Mastodon bearer token."},{base:"mastodon_mock_session_tokens",storage:"local",suffix:"none",sensitivity:"secret",note:"Bearer token per saved session, keyed by session id. Split out of mastodon_mock_sessions so the account list can be exported."},{base:"mockingbird_bsky_credentials",storage:"local",suffix:"account",sensitivity:"secret",note:"Bluesky access + refresh JWTs. Split out of mockingbird_bsky_profile."},{base:"mockingbird_bsky_identity_credentials",storage:"local",suffix:"none",sensitivity:"secret",note:"JWTs for a Bluesky-PRIMARY account \u2014 the one the app is signed in as, not a connector. Unscoped, unlike mockingbird_bsky_credentials: scoping it by the active account would be circular, since the scope suffix is derived from this account\u2019s own DID. Same reasoning (and same treatment) as mastodon_mock_session_tokens."},{base:"mockingbird_mastodon_connector_token",storage:"local",suffix:"account",sensitivity:"secret",note:"Bearer token for a Mastodon CONNECTOR \u2014 Mastodon attached to a Bluesky-primary account, not the identity itself. Split out of mockingbird_mastodon_connector so the server can be exported and the credential cannot. Account-scoped, unlike mastodon_mock_session_tokens: a connector hangs off one identity."},{base:"mockingbird_github_credentials",storage:"local",suffix:"account",sensitivity:"secret",note:"GitHub personal access token. Split out of mockingbird_github_user."},{base:"mockingbird_raindrop_token",storage:"local",suffix:"none",sensitivity:"secret",note:"Raindrop.io test token. Unscoped: one bookmark drawer per browser, shared by every account. An account-suffixed copy from before that change is adopted on first read and may linger."},{base:"mockingbird_mataroa_connection",storage:"local",suffix:"account",sensitivity:"secret",note:"Mataroa API key plus the linked public blog URL and profile-feed opt-in. Account-scoped because the blog is part of one public persona."},{base:"mockingbird_hugo_credentials",storage:"local",suffix:"account",sensitivity:"secret",note:"Fine-grained GitHub token with write access to the Hugo blog repository. Deliberately separate from mockingbird_github_credentials, which is read-only."},{base:"mockingbird_gist_credentials",storage:"local",suffix:"account",sensitivity:"secret",note:"GitHub token with the gist scope, for publishing pastes as gists. Deliberately separate from mockingbird_github_credentials (read-only) and mockingbird_hugo_credentials (one repo): sharing one token would widen what a single leaked string reaches."},{base:"mockingbird_gist_profile",storage:"local",suffix:"account",sensitivity:"private",note:"The GitHub login the gist token belongs to, so the provider can name itself. Split out of mockingbird_gist_credentials so a settings export can say gists are on without carrying the token."},{base:"mockingbird_posse_queue",storage:"local",suffix:"account",sensitivity:"private",note:"Interactions (likes, boosts, replies) waiting to be recorded to the Hugo blog. Holds no credentials \u2014 public post URLs and the user\u2019s own reply text. Account-scoped because a POSSE record is a claim by one persona."},{base:"mockingbird_hugo_repo",storage:"local",suffix:"account",sensitivity:"private",note:"Hugo blog repository coordinates: owner, repo, branch, content path, public site URL, profile-feed opt-in. Account-scoped because the blog is part of one public persona."},{base:"mockingbird_paste_edit_keys",storage:"local",suffix:"none",sensitivity:"secret",note:"Per-paste edit codes. A bearer capability: whoever holds one can rewrite or delete that paste. Split out of mockingbird_pastes."},{base:"mockingbird_pastepile_key",storage:"local",suffix:"none",sensitivity:"secret",note:'Optional Pastepile API key plus its revocation secret. Free and account-less; it tags created pastes so they are listable under scope=mine ("My pastes"). Unscoped: it authorises this browser to talk to a pastebin, not one persona \u2014 which feeds a persona subscribes to stays per account. Retention-governed like the other pasted tokens.'},{base:"mockingbird_cors_proxy_key",storage:"local",suffix:"none",sensitivity:"secret",note:"CORS proxy API key, plus the header name a custom proxy wants it in. Billable on a paid plan, so it is retention-governed like the other pasted tokens. Unscoped: the subscription belongs to the human, not to one persona. Split out of mockingbird_cors_proxy so the proxy choice itself stays exportable."},{base:"mockingbird_twitter_keys",storage:"local",suffix:"none",sensitivity:"secret",note:"API keys for the Twitter/X read services (per service, each with its own retention stamp). Billable on a paid plan and able to read on the user's behalf, so it is treated exactly like the other pasted tokens. Unscoped: the subscription belongs to the human, not to one persona."},{base:"mockingbird_shortener_keys",storage:"local",suffix:"none",sensitivity:"secret",note:"API keys for the link shorteners (Dub, Short.io, T.LY), one per service, each with its own retention stamp. A key here can create, re-point and delete links on a domain the user publishes under, so it is treated exactly like the other pasted tokens. Unscoped: the subscription belongs to the human, not to one persona. Split out of mockingbird_shortener so the service choice stays exportable."},{base:"mastodon_mock_sessions",storage:"local",suffix:"none",sensitivity:"private",note:"Which accounts on which instances. Identity, not credentials \u2014 the tokens live in mastodon_mock_session_tokens."},{base:"mastodon_mock_server",storage:"local",suffix:"none",sensitivity:"private",note:"Home instance. Names where the user is; a niche instance can be identifying on its own."},{base:"mockingbird_bsky_profile",storage:"local",suffix:"account",sensitivity:"private",note:"Linked Bluesky handle, DID, display name, avatar, resolved PDS."},{base:"mockingbird_bsky_identity_profile",storage:"local",suffix:"none",sensitivity:"private",note:"Who a Bluesky-PRIMARY account is: handle, DID, display name, avatar. Identity, not credentials \u2014 the JWTs live in mockingbird_bsky_identity_credentials, exactly as mastodon_mock_sessions splits from its tokens. Exportable so a personal backup can record which account was primary; the export cannot authenticate as it."},{base:"mockingbird_mastodon_connector",storage:"local",suffix:"account",sensitivity:"private",note:"Which Mastodon server a Bluesky-primary account opted into reading, and whether it has credentials there. The token lives in mockingbird_mastodon_connector_token. Private rather than setting: naming the instance you read is a disclosure, same reasoning as mastodon_mock_server."},{base:"mockingbird_github_user",storage:"local",suffix:"account",sensitivity:"private",note:"Linked GitHub login and profile."},{base:"mockingbird_anonymous_account",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"The browser-local Anonymous profile."},{base:"mockingbird_anonymous_follows",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"Who the Anonymous account follows."},{base:"mockingbird_anonymous_bookmarks",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"What the Anonymous account saved."},{base:"mockingbird_anonymous_lists",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"Anonymous account lists and their members."},{base:"mockingbird_anonymous_tags",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"Followed hashtags. The canonical example of privacy-sensitive-but-not-secret: a health or identity tag published in a gist is a disclosure."},{base:"mockingbird_rss_feeds",storage:"local",suffix:"account",sensitivity:"private",note:"Subscribed feed URLs \u2014 what the user reads. Private feed URLs (Feedbin, Miniflux, Google Alerts) routinely embed an API key in the URL itself; by a decided business rule these are stored as-is and NOT treated as secrets, and no warning is shown \u2014 see mawkingbird_profile/docs/01-data-model.md. Real secret storage is future work. Each feed also carries its opt-in flag for the CORS proxy."},{base:"mockingbird_cors_proxy",storage:"local",suffix:"none",sensitivity:"private",note:"Which CORS proxy is selected, and a self-hosted proxy's URL template. Not secret \u2014 the key half lives in mockingbird_cors_proxy_key \u2014 but a custom template names a host the user runs."},{base:"mockingbird_shortener",storage:"local",suffix:"none",sensitivity:"private",note:"Which link shortener is active, and the short domain configured for each. Not secret \u2014 the keys live in mockingbird_shortener_keys \u2014 but a branded domain names the user, which is rather the point of one."},{base:"mockingbird_twitter",storage:"local",suffix:"none",sensitivity:"private",note:"Which Twitter/X read service is selected, and the cached verdict on whether it can be reached from a browser at all. Not secret \u2014 the keys live in mockingbird_twitter_keys \u2014 but naming the service you read through is a disclosure, same reasoning as mockingbird_cors_proxy."},{base:"mockingbird_twitter_follows",storage:"local",suffix:"account",sensitivity:"private",note:"Which Twitter/X accounts are followed into the timeline. A follow list: not a credential, and squarely the kind of thing that should never reach a published gist."},{base:"mockingbird_nitter_host",storage:"local",suffix:"none",sensitivity:"private",note:"The Nitter instance used for Twitter/X reads, replaceable when one dies. Private rather than setting for the same reason as mastodon_mock_server: a niche instance names where the reader goes."},{base:"mockingbird_trusted_accounts",storage:"local",suffix:"account",sensitivity:"private",note:"Accounts the reader marked as trusted, and the trust level each was given. A judgement about named people \u2014 closer to mockingbird_local_moderation than to a preference, and the kind of list that reads very differently out of context."},{base:"mockingbird_proxy_consent",storage:"local",suffix:"none",sensitivity:"private",note:"Which (service, CORS proxy) pairings the user agreed to send an API key through, and when. Supersedes mockingbird_shortener_proxy_consent, which is folded in on first read. Holds no credential itself, but it records a security decision: exporting and re-importing it elsewhere would carry consent the person never gave in that browser."},{base:"mockingbird_shortener_proxy_consent",storage:"local",suffix:"none",sensitivity:"private",note:"Which (shortener, CORS proxy) pairings the user agreed to send an API key through, and when. Holds no credential itself, but it records a security decision: exporting it and re-importing elsewhere would carry consent the person never gave in that browser."},{base:"mockingbird_paste_feeds",storage:"local",suffix:"account",sensitivity:"private",note:"Subscribed paste feeds \u2014 what the user reads, and whether each goes through the CORS proxy. Scoped per account: following a feed as one persona says nothing about what the others want in their timeline. An unscoped list from before that change is adopted by the first account to read it."},{base:"mockingbird_saved_searches",storage:"local",suffix:"account",sensitivity:"private",note:"Saved search terms. Reveals interests as directly as a tag subscription does."},{base:"mockingbird_local_moderation",storage:"local",suffix:"none",sensitivity:"private",note:"Muted words, accounts and domains. Often discloses more than a follow list."},{base:"mockingbird_muted_posts",storage:"local",suffix:"none",sensitivity:"private",note:"Individually hidden posts."},{base:"mockingbird_eliza_following",storage:"local",suffix:"account",sensitivity:"private",note:"Whether the local Eliza account is followed."},{base:"mockingbird_rail_profile",storage:"local",suffix:"account",sensitivity:"private",note:"Which profile cards are pinned to the rail \u2014 named accounts."},{base:"mockingbird_chat_read",storage:"local",suffix:"none",sensitivity:"private",note:"Per-conversation read markers; the conversation ids identify correspondents."},{base:"mockingbird_dismissed_announcements",storage:"local",suffix:"none",sensitivity:"private",note:"Dismissed announcement ids \u2014 server-specific, so it points at the instance."},{base:"mockingbird_house_ad_clicks",storage:"local",suffix:"none",sensitivity:"private",note:"How many times each right-rail house ad was clicked, and when. Local only \u2014 never sent anywhere."},{base:"mockingbird_route_log",storage:"local",suffix:"none",sensitivity:"private",note:"Per-route visit counts and time spent, for the Observability page. Paths are sanitized (no ids or queries). Local only \u2014 never sent anywhere."},{base:"mockingbird_drafts",storage:"local",suffix:"none",sensitivity:"content",note:"Unpublished post drafts."},{base:"mockingbird_compose_autosave",storage:"local",suffix:"none",sensitivity:"content",note:"In-progress composer text."},{base:"mockingbird_pastes",storage:"local",suffix:"none",sensitivity:"content",note:"Paste history including bodies. Edit codes are NOT here \u2014 see mockingbird_paste_edit_keys."},{base:"mockingbird_short_links",storage:"local",suffix:"none",sensitivity:"content",note:"Short links this browser created: destination, short URL and the provider id needed to edit or delete them. Content rather than private because the destinations are things the user chose to publish. Link passwords are deliberately never stored here."},{base:"mockingbird_conversations",storage:"local",suffix:"account",sensitivity:"content",note:"Local DM threads with in-app correspondents, message bodies included. Capped per correspondent and per conversation, but the cap is a size limit, not a privacy measure \u2014 a truncated private conversation is still a private conversation."},{base:"mockingbird_local_posts",storage:"local",suffix:"account",sensitivity:"content",note:"Locally-composed posts."},{base:"mockingbird_write_workspace",storage:"local",suffix:"account",sensitivity:"content",note:"The writing board: draft cards, their column placement and split-view layout. Holds draft text, so it is content rather than a setting even though the layout half of it is only a preference."},{base:"mockingbird_client_prefs",storage:"local",suffix:"none",sensitivity:"setting",note:"Theme, accent, reader typography, composer behaviour. The bulk of a shareable setup."},{base:"mockingbird_house_ads",storage:"local",suffix:"none",sensitivity:"setting",note:"Whether right-rail house ads show at all, and which ones are switched off individually. Unscoped: an opinion about an ad belongs to the person, not to one persona."},{base:"mockingbird_default_visibility",storage:"local",suffix:"account",sensitivity:"setting",note:"Default post visibility."},{base:"mockingbird_hidden_providers",storage:"local",suffix:"account",sensitivity:"setting",note:"Which providers are hidden from the merged timeline."},{base:"mockingbird_just_my_server",storage:"local",suffix:"account",sensitivity:"setting",note:"Whether Home uses the generated same-server friends list."},{base:"mockingbird_feature_flags",storage:"local",suffix:"none",sensitivity:"setting",note:"Opt-in feature toggles."},{base:"mockingbird_credential_lifetime",storage:"local",suffix:"account",sensitivity:"setting",note:"Connector credential retention policy (30d / 90d / never)."},{base:"mockingbird_pkm_vocabulary",storage:"local",suffix:"account",sensitivity:"setting",note:"The words that mean #NOTE, #TODO and #CAL for this account. Account-scoped because they are language-specific \u2014 an English account and a German one want different words, and a global setting would make one of them wrong on every switch."},{base:"mockingbird_rss_feed_limit",storage:"local",suffix:"account",sensitivity:"setting",note:"How many RSS feeds to pull into the timeline. A number, not a list \u2014 the subscriptions themselves are mockingbird_rss_feeds and are private."},{base:"mockingbird_anonymous_preferences",storage:"local",suffix:"none",sensitivity:"setting",group:"anonymous",note:"Preferences for the Anonymous account."},{base:"mockingbird_search_server_v1",storage:"local",suffix:"none",sensitivity:"setting",note:"Optional separate search instance. Names a host, but choosing one is a config tip worth sharing."},{base:"mockingbird_translation_preference",storage:"local",suffix:"none",sensitivity:"setting",note:"Which translator the \u{1F310} button uses: your server, AI via OpenRouter, or ask each time. Absent means the default (your server)."},{base:"mockingbird_client_lists",storage:"local",suffix:"account",sensitivity:"setting",note:"Browser-local lists of accounts, stored as handles. Works signed out, and unlike server lists does not require following anyone. Treated as cache: a version bump discards it."},{base:"mockingbird_tag_bundles",storage:"local",suffix:"account",sensitivity:"setting",note:"Named bundles of hashtags read as one feed, capped at 10 tags each. Works signed out. Treated as cache: a version bump discards it."},{base:"mockingbird_translation_usage",storage:"local",suffix:"none",sensitivity:"setting",note:"Daily translation counts and limits, held separately for the Mastodon endpoint and OpenRouter. Counts only \u2014 never what was translated."},{base:"mockingbird_search_server_rejects_v1",storage:"local",suffix:"none",sensitivity:"setting",note:"Servers already checked and rejected as search servers, so a hunt does not re-probe the same duds. Clearable from Settings \u2192 Server."},{base:"mockingbird_follow_nudge_dismissed",storage:"local",suffix:"none",sensitivity:"setting",note:"Whether the follow nudge was dismissed."},{base:"mastodon_mock_account_mode",storage:"local",suffix:"none",sensitivity:"setting",note:"Which kind of account was last active: mastodon, bluesky or anonymous."},{base:"mastodon_mock_server_index",storage:"local",suffix:"none",sensitivity:"cache",note:"Curated joinmastodon instance index."},{base:"mockingbird_server_about_v1",storage:"local",suffix:"none",sensitivity:"cache",note:"Cached instance /about payloads."},{base:"mockingbird_feed_capability_v1",storage:"local",suffix:"none",sensitivity:"cache",note:"Which feeds (local/federated timelines, the three trends endpoints) each host actually serves, so we stop linking to feeds that answer 404 or 422 there. Keyed by host and by whether we held a token, because those answers genuinely differ. Refetchable, 24h TTL, records no content."},{base:"mockingbird_twitter_usage",storage:"local",suffix:"none",sensitivity:"cache",note:"Daily Twitter/X request counts against the reader's own budget, bucketed by local calendar day. Counters only \u2014 resetting them loses nothing but the day's tally."},{base:"mockingbird_article_quota",storage:"local",suffix:"none",sensitivity:"cache",note:"Daily count of reader article expansions against the free limit, bucketed by local calendar day. A counter and a date \u2014 resetting it loses nothing but today's tally."},{base:"mockingbird_first_run_preview",storage:"local",suffix:"none",sensitivity:"cache",note:"In-flight first-run state: the server the preview seeded from, and which follows already existed so the seed can be removed cleanly. Exists only while the first-run modal is open and is deleted when it closes \u2014 a half-finished onboarding is not something to carry to another machine."},{base:"mockingbird_cors_proxy_usage",storage:"local",suffix:"none",sensitivity:"cache",note:"Counts of proxied requests and failures, for the Observability page. Diagnostics, not settings \u2014 resetting them loses nothing. Deliberately counters only: no URLs, so it never records which feeds were read."},{base:"mockingbird_search_server_about_v1",storage:"local",suffix:"none",sensitivity:"cache",note:"Cached search-instance /about payloads."},{base:"mockingbird_instance_status_pages",storage:"local",suffix:"none",sensitivity:"cache",note:"Discovered instance status pages."},{base:"mockingbird_remote_storage_usage",storage:"local",suffix:"none",sensitivity:"cache",note:"Last known remote storage figure from the profile service (bytes used, allowance, tier, when it was read). A cached copy of a server-side number \u2014 resetting it only blanks the display until the next sync."},{base:"mockingbird_mawkingbird_metrics",storage:"local",suffix:"none",sensitivity:"cache",note:"Call counts against Mawkingbird services, split by service and by whether a paid or free token was sent. Diagnostics, not settings \u2014 resetting them loses nothing but the tally."},{base:"mockingbird_api_metrics:",storage:"local",suffix:"instance",sensitivity:"cache",note:"Local API timing metrics and grouped client-error counts, one entry per instance. The trailing colon is part of the base \u2014 keys are `\u2026metrics:<host>`."},{base:"mockingbird_api_metrics",storage:"local",suffix:"none",sensitivity:"cache",note:"Superseded unscoped metrics blob, replaced by the per-instance keys above. Only ever deleted now; classified so lingering data is still recognised."},{base:"mockingbird_anonymous_home_feed",storage:"local",suffix:"none",sensitivity:"cache",group:"anonymous",note:"Cached Anonymous home timeline. Derived from private follow data."},{base:"mockingbird_anonymous_feed_corpus",storage:"local",suffix:"none",sensitivity:"cache",group:"anonymous",note:"Cached posts backing the Anonymous feed. Derived from private follow data."},{base:"mockingbird_raindrop_credentials",storage:"local",suffix:"account",sensitivity:"secret",note:"Legacy key from the superseded Raindrop OAuth flow. Only ever deleted now, never written; listed so it is classified if it lingers."},{base:"mastodon_mock_oauth_app",storage:"session",suffix:"none",sensitivity:"secret",note:"In-flight Mastodon OAuth attempt: client secret, PKCE verifier and state."},{base:"mockingbird_openrouter_key",storage:"local",suffix:"none",sensitivity:"secret",note:"OpenRouter API key from the PKCE flow. Can spend the user\u2019s OpenRouter credits. Shared by every account in this browser."},{base:"mockingbird_vault_device",storage:"local",suffix:"none",sensitivity:"setting",note:"A coarse label for this browser, shown when a stored-connection conflict is resolved. Not a fingerprint and not derived from one."},{base:"mockingbird_openrouter_model",storage:"local",suffix:"none",sensitivity:"setting",note:"Chosen OpenRouter model id for the prompt helpers."},{base:"mockingbird_openrouter_prompts",storage:"local",suffix:"none",sensitivity:"setting",note:"User-edited prompt templates for the search and tag helpers. Only present for templates edited away from the shipped default."},{base:"mockingbird_plus_features",storage:"local",suffix:"none",sensitivity:"setting",note:"Which Mawkingbird Plus features are switched on (CORS proxy, settings sync, trust list, client lists, RSS OPML list, test-deployment connection-key sync), and whether the one-time post-sign-in dialog has been answered. Cleared on sign-out so the next account decides for itself."},{base:"mockingbird_config_sync",storage:"local",suffix:"none",sensitivity:"private",note:"Remote configuration URL, check cadence, last verified hash, and check timestamp. Operational sync state is never included in a portable config."},{base:"mockingbird_profile_sync",storage:"local",suffix:"none",sensitivity:"private",note:"Mawkingbird Plus settings-sync state: whether sync is on, the last ETag and revision seen, whether local edits are unpushed, and any persistent failure. Never synced itself \u2014 a document that described its own sync position would be describing the wrong browser the moment it arrived."},{base:"mockingbird_profile_list_copy",storage:"local",suffix:"none",sensitivity:"private",note:"Which Mawkingbird accounts have been offered the one-time copy of this browser's client lists to Plus storage. Records only that the question was asked, never the answer \u2014 declining keeps the copy available on demand, so a stored 'no' would have nothing to gate."},{base:"mockingbird_profile_writer",storage:"local",suffix:"none",sensitivity:"private",note:`A random per-browser id, so a sync conflict can say "your other browser" rather than "someone". Not a fingerprint and not derived from anything: eight random characters, sent only inside the user's own settings document.`},{base:"mockingbird_openrouter_pkce_verifier",storage:"session",suffix:"none",sensitivity:"secret",note:"PKCE verifier for the in-flight OpenRouter authorization."},{base:"mockingbird_openrouter_oauth_state",storage:"session",suffix:"none",sensitivity:"secret",note:"Anti-CSRF state for the in-flight OpenRouter authorization."},{base:"mockingbird_dropbox_token",storage:"session",suffix:"none",sensitivity:"secret",note:"Short-lived Dropbox online access token."},{base:"mockingbird_dropbox_pkce_verifier",storage:"session",suffix:"none",sensitivity:"secret",note:"PKCE verifier for the in-flight Dropbox authorization."},{base:"mockingbird_dropbox_oauth_state",storage:"session",suffix:"none",sensitivity:"secret",note:"Anti-CSRF state for the in-flight Dropbox authorization."},{base:"mockingbird_blogger_token",storage:"session",suffix:"account",sensitivity:"secret",note:"Short-lived Google access token."},{base:"mockingbird_blogger_blog",storage:"local",suffix:"account",sensitivity:"private",note:"Chosen Blogger blog (id, name, address) and the profile-feed opt-in."},{base:"mockingbird_blogger_client_id",storage:"local",suffix:"none",sensitivity:"setting",note:"The user's own Google OAuth client id, overriding the build's."},{base:"mockingbird_blogger_pkce_verifier",storage:"session",suffix:"none",sensitivity:"secret",note:"PKCE verifier for the in-flight Blogger authorization."},{base:"mockingbird_blogger_oauth_state",storage:"session",suffix:"none",sensitivity:"secret",note:"Anti-CSRF state for the in-flight Blogger authorization."},{base:"mockingbird.update-recovery",storage:"session",suffix:"none",sensitivity:"cache",note:"Reload-attempt bookkeeping for post-deployment chunk recovery."}];function i(t,e){switch(t.suffix){case"none":return e===t.base;case"account":return e===t.base||e.startsWith(`${t.base}_`);case"instance":return e.startsWith(t.base)}}function n(t){let e=null;for(let s of o)i(s,t)&&(e===null||s.base.length>e.base.length)&&(e=s);return e}export{o as a,i as b,n as c};
